const t=[{id:"paper-presentation",name:"Paper Presentation",category:"Technical",icon:"FileText",shortDescription:"Explore your ideas, research, and technical knowledge through an exciting Paper Presentation in an ECE-related domain.",description:"Present innovative solutions, share your research, and showcase your ideas in an ECE-related domain. Get ready to present your work, interact with the judges, and make an impact!",rules:["Participants can participate individually (solo) or as a team of up to 4 members.","The paper must be related to any ECE-related domain.","Each participant/team will be given 7 minutes to present their paper.","Judges will have 3 minutes to ask questions and interact with the participants.","Participants can use 7–10 slides for their presentation.","The presented work should be original and properly acknowledge any referenced sources.","Participants should bring their presentation file in a compatible format.","The decision of the judges and Organizing Committee will be final and binding."]},{id:"project-presentation",name:"Project Presentation",category:"Technical",icon:"Cpu",shortDescription:"Showcase your innovative hardware project and demonstrate your creativity, technical knowledge, and problem-solving skills.",description:"Present your working hardware project, explain its concept and implementation, and impress the judges through your project demonstration and viva.",rules:["Participants can participate individually (solo) or as a team of 4 members.","Displaying the project abstract on an A3 sheet is mandatory for every team.","This is a hardware project presentation; a PPT presentation is not required.","Each team should bring the necessary cables and accessories required for their project demonstration.","Projects will be evaluated based on novelty, working and execution, presentation, and viva."],domains:[{title:"Embedded & Intelligent Systems",sub:["Embedded Systems & IoT","Cyber-Physical Systems"]},{title:"Semiconductor & Hardware Technology",sub:["VLSI & Semiconductor Systems"]},{title:"Communication & Wireless Technology",sub:["Communication & Wireless Technologies","RF, Microwave & Antenna Systems","Future Communication Technologies – 5G/6G"]},{title:"Robotics & Autonomous Technology",sub:["Robotics & Automation","Drone & Autonomous Systems"]},{title:"AI, Signal & Vision Technology",sub:["Artificial Intelligence in Electronics","Signal, Image & Video Processing"]},{title:"Sensing & Instrumentation",sub:["Smart Sensors & Instrumentation"]},{title:"Security & Protection Technology",sub:["Electronic Security & Surveillance Systems","Cybersecurity & Smart Security Systems"]},{title:"Healthcare & Human-Centric Technology",sub:["Healthcare & Biomedical Innovation","Assistive & Wearable Electronics"]},{title:"Sustainable, Green & Smart City Technology",sub:["Sustainable & Green Technology","Smart Cities & Infrastructure"]},{title:"Agriculture & Smart Farming",sub:["Agriculture & Smart Farming"]}]},{id:"technical-quiz",name:"Technical Quiz",category:"Technical",icon:"BrainCircuit",shortDescription:"Put your technical knowledge and problem-solving skills to the test with a quiz covering the ECE syllabus and a Circuit Debugging challenge.",description:"The quiz will fully cover the ECE syllabus and also include an engaging Circuit Debugging challenge. Get ready to think smart, solve fast, and showcase your technical skills!",rules:["Each team must consist of 3–4 members.","The quiz will consist of two rounds.","Questions will cover the complete ECE syllabus and core technical concepts.","A Circuit Debugging round will be included to test practical problem-solving skills.","A Semi-Final round may be conducted based on the number of participating teams.","A Tie-Breaker round may be conducted in case of equal scores.","Mobile phones, smart watches, calculators, or other gadgets are not permitted unless specifically allowed by the organizers.","Malpractice, cheating, prompting, or use of unauthorized materials will result in immediate disqualification.","Participants must maintain discipline and fair play throughout the event.","The Quizmaster and Organizing Committee's decision will be final and binding."]},{id:"esports",name:"Free Fire",category:"Non-Technical",icon:"Gamepad2",shortDescription:"Test your skills, strategy, teamwork, and reflexes in an intense Free Fire Clash Squad battle.",description:"Compete as a squad, outplay your opponents, and fight your way to victory. Get ready to communicate, strategize, and become the ultimate champion!",rules:["Game Mode: The match will be played in Clash Squad mode (4v4 squad format).","Character Skills: Character skills will be turned off.","Double Vectors: The use of Double Vectors is strictly banned.","Device: Only mobile devices are allowed.","Map Glitches: Players are not allowed to use any map glitches or exploits.","Grenades & Special Bombs: Grenades and special bombs are not allowed.","Review: Review of gameplay or match situations is allowed.","Gloo Wall: Unlimited Gloo Walls are allowed.","Each member should register separately for the symposium.","Registration fee: Rs. 100 per team on spot."],note:"The Rs. 100 Free Fire team fee is payable on spot and is separate from the Rs. 200 online symposium registration fee."},{id:"dance",name:"Sound Party",category:"Non-Technical",icon:"Music2",shortDescription:"Test your listening skills and music knowledge with BGMs and instrumental music from Tamil movies.",description:"Listen carefully, identify the clues, and answer quickly to score points. Get ready to listen, guess, and have fun!",rules:["Each team must consist of 3–4 members.","The event will consist of 2–3 rounds based on the number of participating teams.","Participants will be played BGM or instrumental music clips related to Tamil movies, songs, actors, actresses, or characters.","Participants will have 30 seconds to 1 minute to identify and answer each question.","Points will be awarded for every correct answer. Negative marks may be given for wrong answers.","A Semi-Final round may be conducted based on the number of participating teams.","A Tie-Breaker round may be conducted in case of equal scores.","Mobile phones, smart watches, or other electronic gadgets are not permitted unless specifically allowed by the organizers.","Malpractice, cheating, prompting, or use of unauthorized materials will result in immediate disqualification.","Participants must maintain discipline, sportsmanship, and fair play throughout the event.","The Quizmaster and Organizing Committee's decision will be final and binding."]},{id:"memory-clash",name:"Memory Clash",category:"Non-Technical",icon:"BrainCog",shortDescription:"Test your memory, concentration, and recall skills — memorize 50 items and recall as many as possible!",description:"Participants will observe and memorize 50 items within a limited time and then recall and name as many items as possible. Stay focused, remember well, and compete to become the Memory Clash champion!",rules:["Two participants will compete in each round, with one participant from each team.","50 items will be displayed for 30 seconds.","Participants must carefully observe and memorize as many items as possible during the 30-second display.","Participants will get 45 seconds to recall and name as many items as possible.","Participants must take turns to answer and say one item at a time.","Repeating an already mentioned item is not allowed.","If a participant gives a wrong answer or pauses for too long, their chance will end.","The same game mechanics will apply to each round.","Two teams will compete, with one member representing each team in a round.","The decision of the Coordinator will be final and binding."]},{id:"cine-cypher",name:"Cine Cypher",category:"Non-Technical",icon:"Clapperboard",shortDescription:"Identify Tamil movies, actors, actresses, songs, and characters through visual and video clues.",description:"Put your movie knowledge, observation skills, and memory to the test in an exciting Cine Cypher. Get ready to think fast, connect the clues, and showcase your cinematic knowledge!",rules:["Each team must consist of 3–4 members.","The game will consist of 2–3 rounds, based on the number of participating teams.","Participants will be shown pictures, clues, symbols, or video clips connected to a Tamil movie, actor, actress, song, or character.","Time limit: 30 seconds to 1 minute per question.","Points will be awarded for every correct answer. Wrong answers will receive negative marks.","A Semi-Final round may be conducted based on the number of participating teams.","A Tie-Breaker round will be conducted if two or more teams have equal scores.","Mobile phones, smart watches, or any other electronic gadgets are not permitted during the game unless allowed by the organizers.","Cheating, prompting, discussing with other teams, or using unauthorized materials will result in immediate disqualification.","Participants must maintain discipline, sportsmanship, and fair play throughout the event.","Once the answer is given, it cannot be changed.","The decision of the Quizmaster and Organizing Committee will be final and binding."]}],a=["Technical","Non-Technical"],n=e=>t.find(i=>i.id===e);export{a,t as e,n as g};
